ViewportWidgetApi *createViewportWidget(QWidget *parent)
{
    return new ViewportWidget(nullptr, parent);
}

ViewportWidgetApi *createViewportWidget(ApplicationSession &session,
                                        QWidget *parent)
{
    return new ViewportWidget(&session, parent);
}

